namespace DrawVerify.Core.Models;
public sealed record ReportTemplateStyle { public string HeadingFontFamily { get; init; } = "Helvetica"; public string BodyFontFamily { get; init; } = "Helvetica"; public string TableFontFamily { get; init; } = "Helvetica"; public double HeadingFontSize { get; init; } = 14; public double BodyFontSize { get; init; } = 9; public double TableFontSize { get; init; } = 8; public string HeaderColor { get; init; } = "#000000"; public string BorderColor { get; init; } = "#000000"; public string HighlightColor { get; init; } = "#FF0000"; public double Margin { get; init; } = 40; public string Orientation { get; init; } = "Portrait"; public void Validate() { if (HeadingFontFamily != "Helvetica" || BodyFontFamily != "Helvetica" || TableFontFamily != "Helvetica") throw new InvalidOperationException("Only Helvetica is supported by the PDF renderer."); if (HeadingFontSize <= 0 || BodyFontSize <= 0 || TableFontSize <= 0 || Margin <= 0) throw new InvalidOperationException("Font sizes and margin must be positive."); if (Orientation is not ("Portrait" or "Landscape")) throw new InvalidOperationException("Orientation must be Portrait or Landscape."); foreach (var color in new[] { HeaderColor, BorderColor, HighlightColor }) if (!System.Text.RegularExpressions.Regex.IsMatch(color, "^#[0-9A-Fa-f]{6}$")) throw new InvalidOperationException($"Invalid color '{color}'."); } }
